133	
134	  private get executionContext(): AgentLoopContext {
135	    return {
136	      config: this.context.config,
137	      promptId: this.agentId,
138	      parentSessionId: this.context.parentSessionId || this.context.promptId, // Always preserve the main agent session ID
139	      geminiClient: this.context.geminiClient,
140	      sandboxManager: this.context.sandboxManager,
141	      toolRegistry: this.toolRegistry,
142	      promptRegistry: this.promptRegistry,
143	      resourceRegistry: this.resourceRegistry,
144	      messageBus: this.toolRegistry.getMessageBus(),
145	    };
146	  }
