148	  /**
149	   * Creates and validates a new `AgentExecutor` instance.
150	   *
151	   * This method ensures that all tools specified in the agent's definition are
152	   * safe for non-interactive use before creating the executor.
153	   *
154	   * @param definition The definition object for the agent.
155	   * @param context The execution context.
156	   * @param onActivity An optional callback to receive activity events.
157	   * @returns A promise that resolves to a new `LocalAgentExecutor` instance.
158	   */
159	  static async create<TOutput extends z.ZodTypeAny>(
160	    definition: LocalAgentDefinition<TOutput>,
161	    context: AgentLoopContext,
162	    onActivity?: ActivityCallback,
163	  ): Promise<LocalAgentExecutor<TOutput>> {
164	    const parentMessageBus = context.messageBus;
165	
166	    // Create an override object to inject the subagent name into tool confirmation requests
167	    const subagentMessageBus = parentMessageBus.derive(definition.name);
168	
169	    // Create isolated registries for this agent instance.
170	    const agentToolRegistry = new ToolRegistry(
171	      context.config,
172	      subagentMessageBus,
173	    );
174	    const agentPromptRegistry = new PromptRegistry();
175	    const agentResourceRegistry = new ResourceRegistry();
176	
177	    if (definition.mcpServers) {
178	      const globalMcpManager = context.config.getMcpClientManager();
179	      if (globalMcpManager) {
180	        for (const [name, config] of Object.entries(definition.mcpServers)) {
181	          await globalMcpManager.maybeDiscoverMcpServer(name, config, {
182	            toolRegistry: agentToolRegistry,
183	            promptRegistry: agentPromptRegistry,
184	            resourceRegistry: agentResourceRegistry,
185	          });
186	        }
187	      }
188	    }
189	
190	    const parentToolRegistry = context.toolRegistry;
191	
192	    const registerToolInstance = (tool: AnyDeclarativeTool) => {
193	      // Check if the tool is an agent tool to prevent recursion.
194	      // We do not allow agents to call other agents.
195	      if (tool.kind === Kind.Agent) {
196	        return;
197	      }
198	
199	      if (tool.name === UPDATE_TOPIC_TOOL_NAME) {
200	        return;
201	      }
202	
203	      // Clone the tool, so it gets its own state and subagent messageBus
204	      const clonedTool = tool.clone(subagentMessageBus);
205	      agentToolRegistry.registerTool(clonedTool);
206	    };
207	
208	    const registerToolByName = (toolName: string) => {
209	      // Handle global wildcard
210	      if (toolName === '*') {
211	        for (const tool of parentToolRegistry.getAllTools()) {
212	          registerToolInstance(tool);
213	        }
214	        return;
215	      }
216	
217	      // Handle MCP wildcards
218	      if (isMcpToolName(toolName)) {
219	        if (toolName === `${MCP_TOOL_PREFIX}*`) {
220	          for (const tool of parentToolRegistry.getAllTools()) {
221	            if (tool instanceof DiscoveredMCPTool) {
222	              registerToolInstance(tool);
223	            }
224	          }
225	          return;
226	        }
227	
228	        const parsed = parseMcpToolName(toolName);
229	        if (parsed.serverName && parsed.toolName === '*') {
230	          for (const tool of parentToolRegistry.getToolsByServer(
231	            parsed.serverName,
232	          )) {
233	            registerToolInstance(tool);
234	          }
235	          return;
236	        }
237	      }
238	
239	      // If the tool is referenced by name, retrieve it from the parent
240	      // registry and register it with the agent's isolated registry.
241	      const tool = parentToolRegistry.getTool(toolName);
242	      if (tool) {
243	        registerToolInstance(tool);
244	      }
245	    };
246	
247	    if (definition.toolConfig) {
248	      for (const toolRef of definition.toolConfig.tools) {
249	        if (typeof toolRef === 'string') {
250	          registerToolByName(toolRef);
251	        } else if (
252	          typeof toolRef === 'object' &&
253	          'name' in toolRef &&
254	          'build' in toolRef
255	        ) {
256	          agentToolRegistry.registerTool(toolRef);
257	        }
258	        // Note: Raw `FunctionDeclaration` objects in the config don't need to be
259	        // registered; their schemas are passed directly to the model later.
260	      }
261	    } else {
262	      // If no tools are explicitly configured, default to all available tools.
263	      for (const toolName of parentToolRegistry.getAllToolNames()) {
264	        registerToolByName(toolName);
265	      }
266	    }
267	
268	    agentToolRegistry.sortTools();
269	
270	    // Register the mandatory completion tool for this agent.
271	    agentToolRegistry.registerTool(
272	      new CompleteTaskTool(
273	        subagentMessageBus,
274	        definition.outputConfig,
275	        definition.processOutput,
276	      ),
277	    );
278	
279	    // Get the parent tool call ID from context
280	    const toolContext = getToolCallContext();
281	    const parentCallId = toolContext?.callId;
282	
283	    return new LocalAgentExecutor(
284	      definition,
285	      context,
286	      agentToolRegistry,
287	      agentPromptRegistry,
288	      agentResourceRegistry,
289	      onActivity,
290	      parentCallId,
291	    );
292	  }
