11	/**
12	 * Mock MessageBus for testing hook execution through MessageBus
13	 */
14	export class MockMessageBus {
15	  private subscriptions = new Map<
16	    MessageBusType,
17	    Set<(message: Message) => void>
18	  >();
19	  publishedMessages: Message[] = [];
20	  defaultToolDecision: 'allow' | 'deny' | 'ask_user' = 'allow';
21	
22	  /**
23	   * Mock publish method that captures messages and simulates responses
24	   */
25	  publish = vi.fn(async (message: Message) => {
26	    this.publishedMessages.push(message);
27	
28	    // Handle tool confirmation requests
29	    if (message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST) {
30	      if (this.defaultToolDecision === 'allow') {
31	        this.emit(MessageBusType.TOOL_CONFIRMATION_RESPONSE, {
32	          type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
33	          correlationId: message.correlationId,
34	          confirmed: true,
35	        });
36	      } else if (this.defaultToolDecision === 'deny') {
37	        this.emit(MessageBusType.TOOL_CONFIRMATION_RESPONSE, {
38	          type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
39	          correlationId: message.correlationId,
40	          confirmed: false,
41	        });
42	      } else {
43	        // ask_user
44	        this.emit(MessageBusType.TOOL_CONFIRMATION_RESPONSE, {
45	          type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
46	          correlationId: message.correlationId,
47	          confirmed: false,
48	          requiresUserConfirmation: true,
49	        });
50	      }
51	    }
52	
53	    // Emit the message to subscribers (mimicking real MessageBus behavior)
54	    this.emit(message.type, message);
55	  });
56	
57	  /**
58	   * Mock subscribe method that stores listeners
59	   */
60	  subscribe = vi.fn(
61	    <T extends Message>(type: T['type'], listener: (message: T) => void) => {
62	      if (!this.subscriptions.has(type)) {
63	        this.subscriptions.set(type, new Set());
64	      }
65	      this.subscriptions.get(type)!.add(listener as (message: Message) => void);
66	    },
67	  );
68	
69	  /**
70	   * Mock unsubscribe method
71	   */
72	  unsubscribe = vi.fn(
73	    <T extends Message>(type: T['type'], listener: (message: T) => void) => {
74	      const listeners = this.subscriptions.get(type);
75	      if (listeners) {
76	        listeners.delete(listener as (message: Message) => void);
77	      }
78	    },
79	  );
80	
81	  /**
82	   * Emit a message to subscribers (for testing)
83	   */
84	  private emit(type: MessageBusType, message: Message) {
85	    const listeners = this.subscriptions.get(type);
86	    if (listeners) {
87	      listeners.forEach((listener) => listener(message));
88	    }
89	  }
90	
91	  /**
92	   * Clear all captured messages (for test isolation)
93	   */
94	  clear() {
95	    this.publishedMessages = [];
96	    this.subscriptions.clear();
97	  }
98	}
99	
100	/**
101	 * Create a mock MessageBus for testing
102	 */
103	export function createMockMessageBus(): MessageBus {
104	  return new MockMessageBus() as unknown as MessageBus;
105	}
106	
107	/**
108	 * Get the MockMessageBus instance from a mocked MessageBus
109	 */
110	export function getMockMessageBusInstance(
111	  messageBus: MessageBus,
112	): MockMessageBus {
113	  return messageBus as unknown as MockMessageBus;
114	}
